119: /*                                                                      */
120: /*      Read a line of text from the given file handle, taking care     */
121: /*      to capture CR and/or LF and strip off ... equivelent of         */
122: /*      DKReadLine().  Pointer to an internal buffer is returned.       */
123: /*      The application shouldn't free it, or depend on it's value      */
124: /*      past the next call to CPLReadLine()                             */
125: /************************************************************************/
126: 
127: const char *CPLReadLine( FILE * fp )
128: {
129: /* -------------------------------------------------------------------- */
130: /*      Cleanup case.                                                   */
131: /* -------------------------------------------------------------------- */
132:     static char	*pszRLBuffer = NULL;
133:     static int	nRLBufferSize = 0;
134:     if( fp == NULL )
135:     {
136:         CPLFree( pszRLBuffer );
137:         pszRLBuffer = NULL;
138:         nRLBufferSize = 0;
139:         return NULL;
140:     }
141: 
142: /* -------------------------------------------------------------------- */
143: /*      Loop reading chunks of the line till we get to the end of       */
144: /*      the line.                                                       */
145: /* -------------------------------------------------------------------- */
146:     int nReadSoFar = 0;
147:     do {
148: /* -------------------------------------------------------------------- */
149: /*      Grow the working buffer if we have it nearly full.  Fail out    */
150: /*      of read line if we can't reallocate it big enough (for          */
151: /*      instance for a _very large_ file with no newlines).             */
152: /* -------------------------------------------------------------------- */
153:         if( nRLBufferSize-nReadSoFar < 128 )
154:         {
155:             nRLBufferSize = nRLBufferSize*2 + 128;
156:             if( pszRLBuffer == NULL )
157:                 pszRLBuffer = (char *) VSIMalloc(nRLBufferSize);
158:             else
159:                 pszRLBuffer = (char *) VSIRealloc(pszRLBuffer, nRLBufferSize);
160:             if( pszRLBuffer == NULL )
161:             {
162:                 nRLBufferSize = 0;
163:                 return NULL;
164:             }
165:         }
166: 
167: /* -------------------------------------------------------------------- */
168: /*      Do the actual read.                                             */
169: /* -------------------------------------------------------------------- */
170:         if( VSIFGets( pszRLBuffer+nReadSoFar, nRLBufferSize-nReadSoFar, fp )
171:             == NULL )
172:         {
173:             CPLFree( pszRLBuffer );
174:             pszRLBuffer = NULL;
175:             nRLBufferSize = 0;
176: 
177:             return NULL;
178:         }
179: 
180:         nReadSoFar = strlen(pszRLBuffer);
181: 
182:     } while( nReadSoFar == nRLBufferSize - 1
183:              && pszRLBuffer[nRLBufferSize-2] != 13
184:              && pszRLBuffer[nRLBufferSize-2] != 10 );
185: 
186: /* -------------------------------------------------------------------- */
