345: /************************************************************************/
346: /*                      CSLTokenizeStringComplex()                      */
347: /*                                                                      */
348: /*      The ultimate tokenizer?                                         */
349: /************************************************************************/
350: 
351: char ** CSLTokenizeStringComplex( const char * pszString,
352:                                   const char * pszDelimiters,
353:                                   int bHonourStrings, int bAllowEmptyTokens )
354: 
355: {
356:     char **papszRetList = NULL;
357:     char *pszToken = (char *) CPLCalloc(10,1);
358:     int nTokenMax = 10;
359: 
360:     while( pszString != NULL && *pszString != '\0' )
361:     {
362:         int	bInString = FALSE;
363: 
364:         int nTokenLen = 0;
365: 
366:         /* Try to find the next delimeter, marking end of token */
367:         for( ; *pszString != '\0'; pszString++ )
368:         {
369: 
370:             /* End if this is a delimeter skip it and break. */
371:             if( !bInString && strchr(pszDelimiters, *pszString) != NULL )
372:             {
373:                 pszString++;
374:                 break;
375:             }
376: 
377:             /* If this is a quote, and we are honouring constant
378:                strings, then process the constant strings, with out delim
379:                but don't copy over the quotes */
380:             if( bHonourStrings && *pszString == '"' )
381:             {
382:                 if( bInString )
383:                 {
384:                     bInString = FALSE;
385:                     continue;
386:                 }
387:                 else
388:                 {
389:                     bInString = TRUE;
390:                     continue;
391:                 }
392:             }
393: 
394:             /* Within string constants we allow for escaped quotes, but
395:                in processing them we will unescape the quotes */
396:             if( bInString && pszString[0] == '\\' && pszString[1] == '"' )
397:             {
398:                 pszString++;
399:             }
400: 
401:             /* Within string constants a \\ sequence reduces to \ */
402:             else if( bInString
403:                      && pszString[0] == '\\' && pszString[1] == '\\' )
404:             {
405:                 pszString++;
406:             }
407: 
408:             if( nTokenLen >= nTokenMax-1 )
409:             {
410:                 nTokenMax = nTokenMax * 2 + 10;
411:                 pszToken = (char *) CPLRealloc( pszToken, nTokenMax );
412:             }
413: 
414:             pszToken[nTokenLen] = *pszString;
415:             nTokenLen++;
416:         }
417: 
418:         pszToken[nTokenLen] = '\0';
419: 
420:         if( pszToken[0] != '\0' || bAllowEmptyTokens )
421:         {
422:             papszRetList = CSLAddString( papszRetList, pszToken );
423:         }
424:     }
425: 
426:     if( papszRetList == NULL )
427:         papszRetList = (char **) CPLCalloc(sizeof(char *),1);
428: 
429:     CPLFree( pszToken );
430: 
431:     return papszRetList;
432: }
