34: int GTIFWriteKeys(GTIF *gt)
35: {
36: 
37:     if (!(gt->gt_flags & FLAG_FILE_MODIFIED)) return 1;
38: 
39:     if( gt->gt_tif == NULL )
40:         return 0;
41: 
42:     TempKeyData tempData;
43:     tempData.tk_asciiParams = 0;
44:     tempData.tk_asciiParamsLength = 0;
