52:     }
53: 
54:     /* Set up header of ProjectionInfo tag */
55:     KeyHeader *header = (KeyHeader *)gt->gt_short;
56:     header->hdr_num_keys = (pinfo_t) gt->gt_num_keys;
57:     header->hdr_version  = gt->gt_version;
58:     header->hdr_rev_major  = gt->gt_rev_major;
59:     header->hdr_rev_minor  = gt->gt_rev_minor;
