64:         GeoKey *keyptr = gt->gt_keys + sortkeys[i];
65:         if (keyptr->gk_type == TYPE_ASCII)
66:         {
67:             tempData.tk_asciiParamsLength += keyptr->gk_count;
68:         }
69:     }
70:     if (tempData.tk_asciiParamsLength > 0)
71:     {
72:         tempData.tk_asciiParams =
73:             (char *)_GTIFcalloc(tempData.tk_asciiParamsLength + 1);
74:         if( tempData.tk_asciiParams == NULL )
75:             return 0;
76:         tempData.tk_asciiParams[tempData.tk_asciiParamsLength] = '\0';
77:     }
78: 
79:     /* Set up the rest of SHORT array properly */
80:     GeoKey *keyptr = gt->gt_keys;
81:     KeyEntry *entptr = (KeyEntry*)(gt->gt_short + 4);
82:     for (int i=0; i< gt->gt_num_keys; i++,entptr++)
83:     {
